(window.CRAM_PERSONAL=window.CRAM_PERSONAL||{})["pharmacology-i-exam-3"]={"title":"Pharmacology I Exam 3","sections":[{"id":"hf-rules","title":"Diuretics & heart failure · what he stressed","style":"--acc:#8c1d12;--acc-bg:#efdfde;--acc-zebra:#f7efee;--acc-ink:#6d170e"},{"id":"hf-nephron","title":"Diuretics · the nephron and where each class works","style":"--acc:#2f4f6b;--acc-bg:#e2e6ea;--acc-zebra:#f0f3f5;--acc-ink:#253e53"},{"id":"hf-loops","title":"Diuretics · loop diuretics","style":"--acc:#1f6f5c;--acc-bg:#e0ebe8;--acc-zebra:#eff5f4;--acc-ink:#185748"},{"id":"hf-thiazides","title":"Diuretics · thiazides","style":"--acc:#4a4f8c;--acc-bg:#e6e6ef;--acc-zebra:#f2f3f7;--acc-ink:#3a3e6d"},{"id":"hf-kspare","title":"Diuretics · potassium-sparing and aldosterone antagonists","style":"--acc:#8c2f3a;--acc-bg:#efe2e3;--acc-zebra:#f7f0f1;--acc-ink:#6d252d"},{"id":"hf-cai","title":"Diuretics · carbonic anhydrase inhibitors","style":"--acc:#b8862f;--acc-bg:#f5eee2;--acc-zebra:#faf7f0;--acc-ink:#906925"},{"id":"hf-hf","title":"Heart failure · types, compensation, non-drug care","style":"--acc:#7a4a9c;--acc-bg:#ece6f1;--acc-zebra:#f6f2f8;--acc-ink:#5f3a7a"},{"id":"hf-core","title":"Heart failure · diuretics, ACE inhibitors, beta blockers","style":"--acc:#3d6b52;--acc-bg:#e4eae7;--acc-zebra:#f1f5f3;--acc-ink:#305340"},{"id":"hf-digoxin","title":"Heart failure · digoxin","style":"--acc:#a8562f;--acc-bg:#f3e7e2;--acc-zebra:#f9f3f0;--acc-ink:#834325"},{"id":"hf-other","title":"Heart failure · other agents","style":"--acc:#4a4f8c;--acc-bg:#e6e6ef;--acc-zebra:#f2f3f7;--acc-ink:#3a3e6d"},{"id":"hf-flags","title":"Deck versus truth · learn the true version","style":"--acc:#8c1d12;--acc-bg:#efdfde;--acc-zebra:#f7efee;--acc-ink:#6d170e"}],"rows":[{"t":"&#9733;&#9733; Mortality or symptoms?","d":"His standing rule for this whole lecture: <b>good for MORTALITY &rarr; the patient should be on it no matter what; good only for SYMPTOMS &rarr; may not be needed all the time.</b> <b>Symptoms only:</b> diuretics and digoxin. <b>Survival:</b> angiotensin-converting enzyme inhibitors (or angiotensin receptor blockers), the three beta blockers, aldosterone antagonists in advanced failure, sacubitril-valsartan, sodium-glucose cotransporter 2 inhibitors.","s":0},{"t":"&#9733;&#9733; Know every drug's effect on potassium","d":"&ldquo;You can kill somebody very easily with potassium.&rdquo; <b>LOWER it:</b> loop diuretics, thiazides, carbonic anhydrase inhibitors. <b>RAISE it:</b> potassium-sparing diuretics, aldosterone antagonists, angiotensin-converting enzyme inhibitors, sacubitril-valsartan. Several drugs on one patient: work out which way the total falls.","s":0},{"t":"&#9733; Where salt goes, water follows","d":"Diuretics work by blocking sodium (and usually chloride) reabsorption somewhere along the nephron, and water leaves with it. Too much fluid: volume overload and pulmonary edema. Too little: volume depletion and cardiovascular collapse.","s":0},{"t":"&#9733; Digoxin level","d":"Digoxin has a very narrow therapeutic index and its level is checked. The slide gives a target range; he said he is <b>probably not going to quiz the specific level</b>. Know the narrow index, not the number.","s":0},{"t":"&#9733; Xanthopsia is the digoxin clue","d":"Yellow-green vision with halos around lights is the classic clue to digoxin toxicity; in his words it is &ldquo;pathognomonic,&rdquo; nothing else does that. (Ivabradine also causes halos and brightness, but without the yellow-green tint.) It means check a level right away.","s":0},{"t":"&#9733; Heart failure decision shape","d":"His rule of thumb: hypertensive patient in decompensated failure &rarr; <b>milrinone</b> (it dilates vessels). Hypotensive patient &rarr; <b>dobutamine or dopamine</b>. Ask what the blood pressure is.","s":0},{"t":"Doses","d":"This site leaves milligram amounts out; doses are not tested in this course, per the earlier lectures. Timings, routes and clinical thresholds are kept.","s":0},{"t":"Why diuretics are dangerous","d":"<b>Diuretic</b> = a drug that increases urine flow and/or sodium chloride excretion. A sustained imbalance of sodium chloride intake against loss is fatal: too much gives volume overload and pulmonary edema; too little gives volume depletion and cardiovascular collapse.","s":1},{"t":"&#9733; Diuretic braking","d":"The kidneys receive about 22% of the cardiac output and fight back against volume loss: <b>sympathetic nervous system and renin-angiotensin-aldosterone system activation, lower blood pressure (less pressure natriuresis), antidiuretic hormone up, renal cell hypertrophy.</b> He called the kidneys &ldquo;divas.&rdquo; This is why diuretics show <b>synergy with angiotensin-converting enzyme inhibitors and calcium channel blockers</b>, which blunt those compensations.","s":1},{"t":"Proximal tubule","d":"<b>60 to 70% of the filtrate is reabsorbed here</b> (glucose, amino acids, organic solutes; weak acids and bases are secreted into the lumen). <b>Carbonic anhydrase inhibitors work here.</b>","s":1},{"t":"Loop of Henle","d":"Concentrates the urine. <b>Descending limb: water leaves the lumen. Ascending limb: 25% of sodium reabsorbed, impermeable to water.</b> <b>Loop diuretics work here.</b>","s":1},{"t":"Distal tubule","d":"About <b>5% of sodium</b> reabsorbed. <b>Thiazide diuretics work here.</b>","s":1},{"t":"Collecting duct","d":"<b>2 to 3% of sodium</b> reabsorbed; <b>aldosterone and antidiuretic hormone</b> act here (antidiuretic hormone opens the water channels). <b>Potassium-sparing diuretics work here.</b> Aldosterone adds sodium channels and pump activity, so sodium is reabsorbed and potassium lost.","s":1},{"t":"&#9733; Order of potency","d":"Loops (inhibit 20 to 25% of sodium chloride reabsorption) &gt; thiazides (up to 5%) &gt; potassium-sparing diuretics and aldosterone antagonists (2 to 3%) &gt; carbonic anhydrase inhibitors (the &ldquo;wimpiest&rdquo;; the early 5% fades to 1 to 3% after 3 to 5 days). He presented the classes in descending order of potency.","s":1},{"t":"&#9733; Agents and mechanism","d":"<b>Furosemide, bumetanide, torsemide, ethacrynic acid</b> (the one that breaks the naming pattern). They inhibit the <b>sodium-potassium-2 chloride carrier</b> on the luminal membrane of the <b>thick ascending limb</b>.","s":2},{"t":"Major actions","d":"Inhibit sodium chloride reabsorption by <b>20 to 25%</b>; urine output up to <b>4 liters a day</b>; <b>more potassium, calcium and magnesium excreted</b> &rarr; hypokalemia, hypocalcemia, hypomagnesemia.","s":2},{"t":"&#9733; Works when the kidneys do not","d":"<b>Loops remain effective when creatinine clearance is below 30 milliliters a minute.</b> Urine flow does not mean the kidneys are working well.","s":2},{"t":"&#9733; Indications","d":"<b>Pulmonary edema, nephrotic syndrome, cirrhosis of the liver (ascites), hypercalcemia (an add-on to saline, which is the main treatment), heart failure, renal failure or insufficiency, hypertension</b> (volume-driven; not good for chronic hypertension).","s":2},{"t":"&#9733; Adverse effects","d":"<b>Volume depletion; hypokalemia (arrhythmias); hyperglycemia; contraction alkalosis; hyperuricemia (gout); ototoxicity</b> (the cochlea; classically hair-cell damage, though often reversible); <b>hyponatremia</b> (seizures); allergic reactions (rash, photosensitivity); <b>azotemia</b> (blood urea nitrogen rises). Loops are the most potent, so they carry the most of these.","s":2},{"t":"Why the side effects happen","d":"<b>Hyperglycemia:</b> low potassium impairs insulin release; catecholamine release; insulin resistance. <b>Gout:</b> volume contraction concentrates uric acid and less is excreted. <b>Metabolic alkalosis:</b> volume depletion plus enhanced hydrogen ion secretion (the major factor). <b>Mild hyperlipidemia</b> from sympathetic activity. Reflex <b>renin, aldosterone and antidiuretic hormone</b> rise.","s":2},{"t":"Vasodilation","d":"Loops also dilate vessels: they stimulate <b>prostaglandin E2 (blocked by non-steroidal anti-inflammatory drugs)</b>, plus a direct muscle-relaxing effect of unknown mechanism.","s":2},{"t":"&#9733; Interactions","d":"<b>Non-steroidal anti-inflammatory drugs</b> blunt the natriuretic and blood pressure response &middot; <b>aminoglycosides</b> potentiate ototoxicity &middot; <b>warfarin</b> competes for plasma protein binding &middot; <b>lithium</b> clearance falls and toxicity rises &middot; <b>digitalis</b>: hypokalemia plus hypomagnesemia gives arrhythmias.","s":2},{"t":"FLAG: boxed warning","d":"<b>FDA boxed warning, not on the slide:</b> furosemide, bumetanide and ethacrynic acid carry a boxed warning for profound diuresis with water and electrolyte depletion when given in excess. Torsemide does not.","s":2},{"t":"&#9733; Agents and mechanism","d":"<b>Chlorothiazide, hydrochlorothiazide, chlorthalidone, metolazone, indapamide.</b> They inhibit the <b>sodium/chloride transporter in the distal convoluted tubule</b> (major action).","s":3},{"t":"Major actions","d":"Inhibit up to <b>5%</b> of filtered sodium chloride; urine output <b>1 to 2 liters a day</b>; <b>more potassium and magnesium excreted; LESS calcium excreted</b> (more calcium reabsorbed in the proximal and distal tubules). Acutely lower the glomerular filtration rate.","s":3},{"t":"&#9733; The calcium paradox","d":"Thiazides <b>keep calcium from being excreted</b>, so they help patients with <b>calcium oxalate kidney stones</b> yet can cause a small rise in <b>serum calcium</b>. Less calcium in the urine means less to crystallize. Loops do the opposite.","s":3},{"t":"&#9733; Hypertension","d":"Cheap, old and well tolerated. He described them as a useful second- or third-line <b>add-on</b> (current hypertension guidelines still list thiazides among first-line choices). Works best in <b>elderly patients, African American patients and sodium-retentive states</b>. Short term: lower blood volume and cardiac output; chronic: vessel relaxation, less sodium &ldquo;waterlogging&rdquo; of vessel walls, lower total peripheral resistance. <b>Low-dose thiazides are preferred</b>, with few adverse effects.","s":3},{"t":"Other indications","d":"Hypertension, renal failure, cirrhosis of the liver, congestive heart failure, renal calcium stones.","s":3},{"t":"&#9733; Adverse effects","d":"Volume depletion with reflex sympathetic and renin-angiotensin-aldosterone activation; <b>hypokalemia; metabolic alkalosis; hyperuricemia (gout); hyperglycemia (less insulin); hypercalcemia; hyperlipidemia</b> (a modest rise in low-density lipoprotein); rash, <b>photosensitivity</b>; dizziness, headache, weakness, restlessness; <b>sexual dysfunction; constipation</b>. Much of the loop list, only milder; the differences are that thiazides RAISE calcium and are not ototoxic.","s":3},{"t":"&#9733;&#9733; Metolazone","d":"Thiazides lose effect at low creatinine clearance, but <b>metolazone still works</b>. His mnemonic: <b>&ldquo;metolazone could make a rock pee&rdquo;</b>. (FLAG, see the last topic: do not treat &ldquo;thiazides do not work in kidney failure&rdquo; as absolute.)","s":3},{"t":"&#9733; Interactions","d":"<b>Non-steroidal anti-inflammatory drugs</b> block prostaglandins and weaken the natriuretic action. <b>Digitalis toxicity</b> rises with potassium loss: keep potassium above 4.0 milliequivalents per liter.","s":3},{"t":"&#9733; Potassium-sparing: agents and mechanism","d":"<b>Amiloride and triamterene</b> <b>block luminal sodium channels</b> in the collecting duct, inhibiting 2 to 3% of sodium chloride reabsorption and <b>decreasing the gradient for potassium secretion</b>. Modest increase in urine flow. Combination products with hydrochlorothiazide exist.","s":4},{"t":"Potassium-sparing: use","d":"Same indications as the others but <b>much less natriuretic and diuretic effect</b>; <b>most often combined with another diuretic or an antihypertensive</b>. A loop plus a potassium-sparing drug offsets the potassium loss.","s":4},{"t":"&#9733; Potassium-sparing: adverse effects","d":"<b>Hyperkalemia</b> (the major difference from other diuretics); caution with <b>angiotensin-converting enzyme inhibitors, angiotensin blockers and potassium supplements</b>; glucose intolerance in diabetes; <b>megaloblastic anemia (triamterene)</b>; <b>azotemia (amiloride)</b>. Salt substitutes are usually <b>potassium chloride</b>, a hidden potassium source.","s":4},{"t":"FLAG: boxed warning","d":"<b>FDA boxed warning, not on the slide:</b> amiloride and triamterene both carry a boxed warning for hyperkalemia.","s":4},{"t":"Aldosterone: normal action","d":"Aldosterone binds its receptor, moves to the nucleus and drives protein synthesis: <b>more sodium channels, more sodium-potassium pump activity, more energy production in the distal tubule</b>.","s":4},{"t":"&#9733; Aldosterone antagonists: agents and mechanism","d":"<b>Spironolactone, eplerenone.</b> They <b>bind the steroid receptor but do not move to the nucleus</b>, so they work best when aldosterone is high. Block 2 to 3% of sodium chloride reabsorption and reduce potassium loss; modest effect on lipids, glucose and uric acid.","s":4},{"t":"&#9733; Aldosterone antagonists: indications","d":"<b>Primary aldosteronism, hypertension, heart failure, edematous conditions, cirrhosis (secondary hyperaldosteronism), nephrotic syndrome.</b> Heart failure is the big one: advanced (class III or IV) failure; see FLAG.","s":4},{"t":"&#9733;&#9733; Aldosterone antagonists: adverse effects","d":"<b>Hyperkalemia and mild acidosis</b>; nausea, vomiting, gastrointestinal upset; <b>sex-hormone effects of spironolactone</b> (it blocks the androgen receptor; see FLAG) &rarr; <b>gynecomastia in men; menstrual irregularities in women</b> (the slide also lists testicular atrophy). <b>Eplerenone has less effect on androgen receptors</b>: switch to it if the patient complains of breast development or menstrual problems.","s":4},{"t":"&#9733; Agents and mechanism","d":"<b>Acetazolamide, dichlorphenamide, methazolamide.</b> Inhibit carbonic anhydrase: <b>bicarbonate absorption in the proximal tubule falls by 80 to 90%</b>, less hydrogen ion production, less hydrogen/sodium exchange. Bicarbonate is trapped in the tubule and passed out (alkaline urine, a mild acidification of the patient).","s":5},{"t":"Weak and self-limiting","d":"Short term sodium and potassium excretion rises about 5%, but <b>after 3 to 5 days the effect shrinks to 1 to 3%</b> because the rest of the nephron compensates. The wimpiest diuretic.","s":5},{"t":"&#9733; Other uses","d":"<b>Glaucoma</b> (less bicarbonate in the ciliary body: dorzolamide, brinzolamide), <b>epilepsy</b> (metabolic acidosis, central nervous system effects), <b>mountain sickness</b> (acidifies the blood so the patient breathes faster).","s":5},{"t":"&#9733; Adverse effects","d":"<b>Metabolic acidosis</b> (the opposite of the contraction alkalosis of other diuretics), <b>potassium depletion, drowsiness</b>.","s":5},{"t":"Causes","d":"<b>Ischemic heart disease and myocardial infarction (50 to 60% of cases)</b>, hypertension, idiopathic dilated cardiomyopathy; other cardiomyopathies (alcoholic, viral, hypertrophic); drug induced.","s":6},{"t":"&#9733; Systolic dysfunction","d":"<b>Decreased contractility</b> (loss of muscle mass, left ventricular hypertrophy, dilated cardiomyopathies), assessed as a <b>reduced ejection fraction</b> (the slide says below 45%; current practice says 40% or less).","s":6},{"t":"&#9733; Diastolic dysfunction","d":"<b>Impaired relaxation:</b> thicker, stiffer ventricles; ischemia impairs removal of calcium back into the sarcoplasmic reticulum; less filling means less cardiac output. Symptoms with a <b>preserved ejection fraction</b>.","s":6},{"t":"Compensatory response","d":"<b>More preload</b> (sodium and water retention), <b>vasoconstriction</b>, <b>tachycardia and more contractility</b> (sympathetic activation), left ventricular hypertrophy. A vicious cycle that therapy has to interrupt.","s":6},{"t":"Precipitants of decompensation","d":"<b>Lack of compliance</b> (diet or medicines), uncontrolled hypertension, arrhythmias, inadequate therapy, inappropriate medicines or fluid overload; also acute anginal chest pain, pulmonary infection, emotional stress.","s":6},{"t":"Non-drug therapy","d":"<b>Restrict dietary sodium and fluid</b> (the slide gives 1 to 3 grams of sodium and under 2 liters of fluid a day); physical activity may improve function.","s":6},{"t":"&#9733;&#9733; Diuretics in heart failure","d":"<b>Loops are the mainstay</b>; thiazides are not potent enough for most patients. They cut sodium and water retention and so <b>preload</b>, for <b>symptomatic benefit only</b>: <b>no evidence they slow progression or lower mortality</b>, and <b>not mandatory</b> (some patients take them as needed). <b>Daily weights</b> detect fluid overload.","s":7},{"t":"&#9733; Angiotensin-converting enzyme inhibitors: what they do","d":"<b>Lower preload, afterload and sympathetic activation; reduce left ventricular hypertrophy, dilation and remodeling; slow progression; lower mortality.</b> Hemodynamics, exercise tolerance, symptoms, admissions, progression and survival all improve. <b>Angiotensin-converting enzyme inhibitors or angiotensin receptor blockers have to be mandatory</b> in heart failure with reduced ejection fraction (a weak pumping heart; the slide does not name the type).","s":7},{"t":"Angiotensin-converting enzyme inhibitor problems","d":"<b>Renal function impairment, hypotension, raised serum potassium, cough, angioedema.</b> Loops lower potassium, angiotensin-converting enzyme inhibitors raise it: monitor.","s":7},{"t":"&#9733;&#9733; Beta blockers: only three","d":"Beta blockers were classically considered contraindicated in heart failure. The ones with a <b>mortality benefit</b> are <b>carvedilol, metoprolol succinate (the extended-release form) and bisoprolol</b>; the others have not shown it.","s":7},{"t":"&#9733; Beta blockers: low and slow","d":"Patient <b>stable before starting</b>; in hospital preferred; <b>very low starting doses</b>; <b>titrate up slowly</b> (the slide says over 6 to 8 weeks total); monitor for worsening heart failure signs and symptoms. Heart rate and contractility fall, so a rushed start can decompensate the patient.","s":7},{"t":"Beta blockers: benefit and place","d":"Better exercise tolerance, a higher ejection fraction, slower progression, fewer hospitalizations, less need for transplant, <b>lower mortality</b>. <b>First line in class II to IV heart failure; patients should be on an angiotensin-converting enzyme inhibitor AND a beta blocker irrespective of symptoms.</b>","s":7},{"t":"Structure and source","d":"<b>Lactone ring and steroid nucleus</b> are essential for activity; the sugar molecules influence absorption, half-life and metabolism.","s":8},{"t":"&#9733; Mechanism","d":"<b>Inhibits the sodium-potassium ATPase</b> &rarr; intracellular sodium rises &rarr; calcium enters through the sodium/calcium exchanger &rarr; <b>force of contraction rises</b> (the older, inotropic mechanism). The newer one is neurohormonal: <b>less sympathetic and more parasympathetic activity, baroreflex resensitized, renin-angiotensin-aldosterone system down</b>, so the heart rate falls (more parasympathetic effect on the atrioventricular node) and cardiac output rises.","s":8},{"t":"&#9733; Narrow therapeutic index","d":"There is little gap between an effective and a toxic level, and it is <b>one of the few heart failure drugs whose level is checked</b>. Target range on the slide: 0.5 to 1 nanogram per milliliter; higher concentrations are associated with worse outcomes in heart failure. He will probably not quiz the number.","s":8},{"t":"&#9733;&#9733; Benefit: symptoms, NOT survival","d":"Better symptoms, exercise tolerance and quality of life; <b>fewer hospitalizations; NO SURVIVAL BENEFIT</b>; no evidence of slowed disease progression. So it is <b>not mandatory</b> like angiotensin-converting enzyme inhibitors and beta blockers.","s":8},{"t":"&#9733; Place in therapy","d":"<b>Symptomatic patients already on optimal angiotensin-converting enzyme inhibitor/beta blocker and diuretic therapy</b>; can be used for <b>rate control in atrial fibrillation with heart failure</b>; considered in symptomatic systolic dysfunction. (FLAG: the slide says &ldquo;first line&rdquo; for the atrial fibrillation case; that is overstated.)","s":8},{"t":"&#9733; Toxicity","d":"<b>Gastrointestinal:</b> anorexia, nausea. <b>Visual:</b> blurred vision, photophobia, <b>xanthopsia, yellow-green halos around lights</b>. <b>Central:</b> delirium, fatigue, confusion, dizziness, abnormal dreams. <b>Cardiac:</b> nodal slowing (longer PR interval, shorter QT interval, depressed ST segment), <b>bradycardia</b>, digoxin-induced afterdepolarization (the tracing shows premature ventricular beats and ST depression).","s":8},{"t":"&#9733;&#9733; Contraindications and risk factors","d":"<b>Advanced atrioventricular block; severe bradycardia or sick sinus syndrome; premature ventricular beats and ventricular tachycardia; Wolff-Parkinson-White syndrome.</b> Toxicity is more likely with <b>hypokalemia, hypomagnesemia and hypercalcemia</b>: loops and thiazides lower potassium and magnesium, so a patient on digoxin plus a diuretic needs electrolyte monitoring. (FLAG: slide 71 prints hyperkalemia; see the last topic.)","s":8},{"t":"&#9733; Antidote: digoxin immune Fab","d":"An <b>antibody fragment made by immunizing healthy sheep</b> with digoxin coupled to human serum albumin; its <b>affinity for digoxin is higher than digoxin's affinity for the sodium-potassium ATPase</b>, so it rapidly reverses toxicity. It can <b>unmask</b> what digoxin was treating (atrial fibrillation or heart failure decompensation).","s":8},{"t":"&#9733; Aldosterone antagonists in heart failure","d":"<b>Spironolactone lowers mortality in advanced (class III or IV) heart failure</b> (the slide says &ldquo;grade&rdquo;) by neurohormonal inhibition and slowed left ventricular remodeling. <b>Not eligible if potassium is above 5 or serum creatinine above 2.5.</b> Gynecomastia in men (about 10%; may respond to a lower dose); <b>eplerenone rarely causes gynecomastia</b>.","s":9},{"t":"Milrinone and inamrinone","d":"<b>Phosphodiesterase type 3 inhibitors</b> (cyclic adenosine monophosphate up): direct stimulation of contraction <b>plus balanced arterial and venous dilation</b> &rarr; lower afterload, higher cardiac output. Approved for <b>short-term intravenous use in acute decompensated heart failure</b>; long-term use carries <b>higher mortality and morbidity than placebo</b>. Adverse: <b>thrombocytopenia (milrinone less), ventricular arrhythmias</b>.","s":9},{"t":"&#9733; Dobutamine and dopamine","d":"<b>Dobutamine: selective beta-1 agonist</b>, intravenous; stimulates force of contraction more than rate; short-term use to stabilize patients. <b>Dopamine</b>: intravenous, acts through dopamine and beta receptors. They vasodilate much less than milrinone, so they suit a <b>hypotensive</b> decompensation; milrinone suits a hypertensive one.","s":9},{"t":"&#9733; Ivabradine","d":"<b>Blocks the hyperpolarization-activated cyclic nucleotide-gated channel</b> (pacemaker current in the sinoatrial node): <b>lowers heart rate without affecting contractility.</b> For patients <b>maxed out on beta blockers</b> who are in <b>normal sinus rhythm with a heart rate above 70</b>; fewer hospitalizations and heart failure deaths. Adverse: <b>atrial fibrillation risk, symptomatic bradycardia, visual impairment (phosphenes, halos, may resolve)</b>. Contraindications resemble beta blockers: hypotension, heart block, pacemaker.","s":9},{"t":"&#9733; Sacubitril-valsartan","d":"Sacubitril is a <b>neprilysin inhibitor</b> (neprilysin normally degrades natriuretic peptide, bradykinin and other vasoactive peptides): vasodilation, natriuresis, diuresis, less myocardial growth and fibrosis. Formulated with <b>valsartan</b>, an angiotensin receptor blocker. Reduces cardiovascular death and hospitalization. <b>Never with an angiotensin-converting enzyme inhibitor: 36-hour washout.</b> Common adverse: hypotension, hyperkalemia, cough, renal insufficiency.","s":9},{"t":"FLAG: sacubitril-valsartan","d":"<b>FDA boxed warning, not on the slide:</b> fetal toxicity. A history of angioedema is also a contraindication.","s":9},{"t":"&#9733; Sodium-glucose cotransporter 2 inhibitors","d":"<b>Dapagliflozin, empagliflozin.</b> For <b>stable chronic heart failure with reduced ejection fraction</b>: <b>reduce mortality and hospitalizations</b>. Originally for diabetes: the kidneys stop reabsorbing glucose. Risks: <b>hypotension and fungal infections of the genitourinary tract</b> (the slide says &ldquo;fungal urinary tract infections&rdquo;). A &ldquo;necessary add-on&rdquo; for heart failure patients.","s":9},{"t":"FLAG: digoxin and potassium","d":"Slide 71 lists <b>hyperkalemia</b> as a digoxin contraindication, and he said &ldquo;hyperkalemic&rdquo; once. Slides 19 and 29 (and the pharmacology) say the opposite: <b>hypokalemia, hypomagnesemia and hypercalcemia raise toxicity risk</b>. Learn hypokalemia.","s":10},{"t":"FLAG: descending limb","d":"The descending limb is <b>permeable to water</b> (the slide: &ldquo;water leaves lumen&rdquo;); he misspoke once. The thick ascending limb is the impermeable one.","s":10},{"t":"FLAG: thiazides and calcium","d":"Slide 24 lists hypercalcemia among thiazide indications. <b>Thiazides raise serum calcium and lower urinary calcium</b>: they treat calcium stones, not hypercalcemia (saline hydration is the main treatment, with a loop diuretic added).","s":10},{"t":"FLAG: thiazides at low clearance","d":"Slide 28: thiazides are ineffective below a creatinine clearance of 30 to 40. Learn <b>metolazone works at low clearance</b>; do not memorize &ldquo;thiazides never work in kidney disease&rdquo; (newer trials show chlorthalidone works in advanced kidney disease).","s":10},{"t":"FLAG: uric acid with thiazides","d":"Slide 23 says thiazides increase uric acid excretion acutely; slide 26 and the clinical picture are <b>hyperuricemia and gout</b>. Learn hyperuricemia.","s":10},{"t":"FLAG: aldosterone antagonists and class","d":"Slide 37 says heart failure &ldquo;class IV&rdquo;; slide 73 says &ldquo;grade III or IV.&rdquo; Learn <b>advanced (class III or IV) heart failure</b>. The slide 36 lines on a 30 to 60 minute lag and on calcium excretion are not carried here.","s":10},{"t":"FLAG: spironolactone and androgen receptors","d":"Slide 38 calls spironolactone a &ldquo;partial agonist at testosterone receptors&rdquo; with &ldquo;weak androgenic effects&rdquo; (he repeated the partial agonist wording). <b>Spironolactone actually BLOCKS (antagonizes) the androgen receptor</b>, which is why it causes gynecomastia and menstrual irregularities. <b>Hirsutism is not an adverse effect of it</b> (the slide lists it, but spironolactone is used to treat hirsutism): do not learn it as one.","s":10},{"t":"FLAG: antidiuretic hormone and water","d":"Slide 10 says water movement in the distal tubule is controlled by aldosterone. <b>Aldosterone drives sodium and potassium handling; antidiuretic hormone controls the collecting duct water channels</b> (slides 11, 30, 34).","s":10},{"t":"FLAG: ejection fraction and weight numbers","d":"Reduced ejection fraction is now <b>40% or less</b> (slide 46 says below 45%). The weight gain of more than 1 pound a day (slide 52) is a teaching figure: <b>learn daily weights, and rapid gain means fluid</b>.","s":10},{"t":"FLAG: dopamine and the kidney","d":"Slide 77 says dopamine infusions maintain renal function. Low-dose dopamine has not been shown to protect the kidneys; do not rely on that claim.","s":10},{"t":"FLAG: carbonic anhydrase notes","d":"Slide 21 (thiazides have some carbonic anhydrase activity and phosphodiesterase inhibition at high doses) and slide 42 (head injury, less swelling) are not examined points: he said not to worry about the carbonic anhydrase action.","s":10},{"t":"Other boxed warnings (not on the slides)","d":"<b>FDA boxed warnings not on the slides:</b> furosemide, bumetanide, ethacrynic acid (profound diuresis); amiloride, triamterene (hyperkalemia); sacubitril-valsartan (fetal toxicity); angiotensin-converting enzyme inhibitors (fetal toxicity); abrupt beta blocker withdrawal (metoprolol).","s":10}],"map":{"pharmacology-i-exam-3-diuretics-k-sparing-cai-quiz-version-2":[33,33,31,63,32,80,42,38,37,38,80,12,-1,12,42,-1,80,39,37,37,31,38],"pharmacology-i-exam-3-diuretics-k-sparing-cai-quiz":[35,80,32,80,80,1,36,35,33,37,32,33,38,80,31,77,80,63,36,36,51,32],"pharmacology-i-exam-3-diuretics-loop-quiz-version-2":[42,20,12,10,18,21,18,72,72,7,-1,19,49,42,10,18,-1,-1,21,77,1,9],"pharmacology-i-exam-3-diuretics-loop-quiz":[12,77,74,10,42,42,-1,18,9,17,10,9,21,49,10,71,42,21,42,77,10,14],"pharmacology-i-exam-3-diuretics-thiazide-quiz-version-2":[42,-1,26,42,23,29,26,26,72,-1,1,42,28,28,42],"pharmacology-i-exam-3-diuretics-thiazide-quiz":[42,42,-1,42,23,72,30,11,30,42,42,42,11,26,26,11],"pharmacology-i-exam-3-hf-digoxin-quiz-version-2":[58,56,56,-1,61,59,56,4,-1,61,62,60,61,4,30,56,55,30],"pharmacology-i-exam-3-hf-digoxin-quiz":[56,30,61,21,61,56,60,55,62,60,62,58,56,60,55,44,60,59,57],"pharmacology-i-exam-3-hf-diuretics-acei-beta-blockers-quiz-version-2":[51,51,45,48,54,45,49,49,47,50,44,49,52,53,53,54,1,44,50,50,46],"pharmacology-i-exam-3-hf-diuretics-acei-beta-blockers-quiz":[56,47,49,45,52,51,43,-1,51,50,54,48,53,46,51,47,50,50,52,54,49,43],"pharmacology-i-exam-3-hf-inotropes-newer-agents-quiz-version-2":[63,68,67,66,67,68,64,64,66,64,69,67,64,66,69,66,65,69,69,64,63,65],"pharmacology-i-exam-3-hf-inotropes-newer-agents-quiz":[67,66,63,67,64,69,66,66,64,64,65,69,66,30,64,69,67,63,67,69,65,66],"pharmacology-i-exam-3-pharm-e3-drill-diuretics-heart-failure":[10,11,80,10,49,72,32,26,33,10,72,37,14,18,-1,-1,21,10,21,29,25,-1,76,33,33,31,76,76,76,63,-1,41,42,80,80,50,51,51,54,53,52,52,52,55,56,56,4,58,59,61,60,62,64,64,65,65,66,66,66,66,67,67,69,69,60,63,41],"pharmacology-i-exam-3-pharm-e3-vignettes-version-2":[-1,29,25,32,66,56,50,64,-1,33,67,51,72,42,64,53,67,-1,-1,52,1,50,45,70,63,62,76,58],"pharmacology-i-exam-3-pharm-e3-vignettes":[69,72,4,-1,66,59,26,47,33,42,-1,37,63,49,70,21,65,33,61,67,49,51,49,4,69,-1,80,66,74]}};
